-- ============================================================================
-- v188: 语文[职高] 14篇必背篇目完整原文补全
-- 为4个默写节点追加完整原文(含注音)，学生可对照原文背诵
-- 幂等: CONCAT追加, 检测"【原文全篇】"避免重复
-- ============================================================================
SET @s = 20;

