-- 4. 现代诗歌默写 (3篇: 我爱这土地/雨巷/致橡树)
-- ═══════════════════════════════════════════════════════════
UPDATE knowledge_nodes SET content = CONCAT(content, '\n\n---\n\n## 📜 原文全篇\n\n### 《我爱这土地》（艾青）\n\n假如我是一只鸟，\n我也应该用嘶哑的喉咙歌唱：\n这被暴风雨所打击着的土地，\n这永远汹涌着我们的悲愤的河流，\n这无止息地吹刮着的激怒的风，\n和那来自林间的无比温柔的黎明……\n——然后我死了，\n连羽毛也腐烂在土地里面。\n\n为什么我的眼里常含泪水？\n因为我对这土地爱得深沉……\n\n> 注：作于1938年抗日战争时期。注意破折号和省略号的使用。\n\n---\n\n### 《雨巷》（戴望舒）\n\n撑着油纸伞，独自\n彷徨在悠长，悠长\n又寂寥的雨巷，\n我希望逢着\n一个丁香一样的\n结着愁怨的姑娘。\n\n她是有\n丁香一样的颜色，\n丁香一样的芬芳，\n丁香一样的忧愁，\n在雨中哀怨，\n哀怨又彷徨。\n\n她彷徨在这寂寥的雨巷，\n撑着油纸伞\n像我一样，\n像我一样地\n默默彳亍着，\n冷漠，凄清，又惆怅。\n\n她静默地走近\n走近，又投出\n太息一般的眼光，\n她飘过\n像梦一般的，\n像梦一般的凄婉迷茫。\n\n像梦中飘过\n一枝丁香的，\n我身旁飘过这女郎；\n她静默地远了，远了，\n到了颓圮的篱墙，\n走尽这雨巷。\n\n在雨的哀曲里，\n消了她的颜色，\n散了她的芬芳，\n消散了，甚至她的\n太息般的眼光，\n丁香般的惆怅。\n\n撑着油纸伞，独自\n彷徨在悠长，悠长\n又寂寥的雨巷，\n我希望飘过\n一个丁香一样的\n结着愁怨的姑娘。\n\n> 注：彳亍(chì chù)、颓圮(tuí pǐ)。戴望舒(1905-1950)，现代派象征主义诗人。\n\n---\n\n### 《致橡树》（舒婷）\n\n我如果爱你——\n绝不像攀援的凌霄花，\n借你的高枝炫耀自己；\n我如果爱你——\n绝不学痴情的鸟儿，\n为绿荫重复单调的歌曲；\n也不止像泉源，\n常年送来清凉的慰藉；\n也不止像险峰，\n增加你的高度，衬托你的威仪。\n甚至日光，\n甚至春雨。\n\n不，这些都还不够！\n我必须是你近旁的一株木棉，\n作为树的形象和你站在一起。\n根，紧握在地下，\n叶，相触在云里。\n每一阵风过，\n我们都互相致意，\n但没有人，\n听懂我们的言语。\n\n你有你的铜枝铁干，\n像刀，像剑，也像戟；\n我有我红硕的花朵，\n像沉重的叹息，\n又像英勇的火炬。\n\n我们分担寒潮、风雷、霹雳；\n我们共享雾霭、流岚、虹霓。\n仿佛永远分离，\n却又终身相依。\n这才是伟大的爱情，\n坚贞就在这里：\n爱——\n不仅爱你伟岸的身躯，\n也爱你坚持的位置，\n足下的土地。\n\n> 注：舒婷(1952-)，原名龚佩瑜，朦胧诗派代表诗人。凌霄、霹雳(pī lì)、霭(ǎi)、岚(lán)、霓(ní)。'), updated_at = NOW() WHERE subject_id = @s AND level = 4 AND name = '现代诗歌默写：我爱这土地、雨巷、致橡树' AND content NOT LIKE '%【原文全篇】%' AND content NOT LIKE '%## 📜 原文全篇%';

SELECT 'v188: 14篇必背篇目原文补全完成！' AS result;
SELECT name, CHAR_LENGTH(content) AS new_len FROM knowledge_nodes WHERE subject_id = @s AND level = 4 AND name LIKE '%默写%' ORDER BY name;
